/*
 * A075256  List of pairs of numbers (a < b) in the sequence {a,b}->
 *          {Max[{a,b}]-Min[{a,b}],k*Min[{a,b}]} with k=3 and the first pair
 *          {a=1,b=2}.
 * https://oeis.org/A075256
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = first element of the n-th flattened pair of the *
 *            sequence generated by the rule {a,b} -> Sort[{Max{a,b}-Min{a,b},
 *            3*Min{a,b}]}. * Initial pair: {1,2}. Output is the sequence of
 *            concatenated pairs. * Recurrence: new pair = {min(d,3*m),
 *            max(d,3*m)} where d = b-a, m = a (the min)
 * Range:     u8 n <= 45, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>  /* for uint64_t if needed */

seq_t a(idx_t n)
{
    /* current pair (sorted ascending) */
    seq_t a_val = 1;          /* smaller element */
    seq_t b_val = 2;          /* larger element */

    /* Number of pairs needed: ceil(n/2) */
    idx_t target_pair = (n + 1) / 2;   /* integer division gives ceil(n/2) */

    /* iterate until we reach the desired pair */
    idx_t i = 1;  /* current pair index (1-based) */
    while (i < target_pair)
    {
        seq_t diff = b_val - a_val;  /* Max - Min */
        seq_t prod = a_val * 3;      /* k * Min, k = 3 */

        /* sort the new pair */
        if (diff < prod) {
            a_val = diff;
            b_val = prod;
        } else {
            a_val = prod;
            b_val = diff;
        }
        ++i;
    }

    /* return the appropriate element of the pair */
    return (n & 1) ? a_val : b_val;
}
